input.command:
cd /tmp/lcm-mock && cat > template.html <<'EOF'
<!doctype html><html><head><meta charset="utf-8"><style>
.wrap{display:grid;grid-template-columns:repeat(auto-fit,minmax(330px,1fr));gap:20px;font-family:var(--font-sans)}
.opt h3{margin:0 0 4px;font-size:14px;color:var(--foreground)}
.opt p{margin:0 0 10px;font-size:12.5px;line-height:1.45;color:var(--muted-foreground)}
.ha{background:#1c1c1c;border-radius:var(--radius);padding:16px;color:#e1e1e1;font-family:Roboto,var(--font-sans);border:1px solid #2c2c2c}
.hero{background:rgba(255,255,255,.04);border-radius:12px;padding:12px 16px;display:flex;flex-direction:column;gap:10px}
.meta{display:flex;align-items:center;gap:10px}
.icon{width:40px;height:40px;border-radius:50%;background:rgba(3,169,244,.15);display:grid;place-items:center}
.icon svg{width:24px;height:24px;fill:#03a9f4}
.chip{font-size:12px;font-weight:600;padding:3px 10px;border-radius:12px;background:rgba(67,160,71,.16);color:#43a047}
.del{margin-left:auto;width:20px;height:20px;fill:#9b9b9b}
.name{font-size:22px;font-weight:600;margin:0}
.row{display:flex;align-items:center;gap:12px}
.lbl{font-size:11px;font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:#9b9b9b;min-width:70px}
.val{font-family:ui-monospace,Menlo,monospace;font-size:22px;letter-spacing:4px;color:#9b9b9b}
.val.small{font-size:18px;letter-spacing:3px}
.unset{font-style:italic;font-size:15px;letter-spacing:0;color:#6f6f6f;font-family:Roboto,sans-serif}
.eye{width:22px;height:22px;fill:#9b9b9b;margin-left:auto}
.sw{width:36px;height:20px;border-radius:10px;background:rgba(3,169,244,.5);position:relative;flex:none}
.sw:after{content:"";position:absolute;right:0;top:0;width:20px;height:20px;border-radius:50%;background:#03a9f4}
.tabs{display:flex;gap:6px}
.tab{display:flex;align-items:center;gap:5px;font-size:12px;font-weight:600;padding:4px 10px 4px 8px;border-radius:14px;color:#9b9b9b;background:rgba(255,255,255,.05);position:relative}
.tab svg{width:16px;height:16px;fill:currentColor}
.tab.on{background:rgba(3,169,244,.18);color:#03a9f4}
.dot{width:6px;height:6px;border-radius:50%;background:#43a047;margin-left:2px}
.input{flex:1;border:none;border-bottom:2px solid #03a9f4;font-family:ui-monospace,Menlo,monospace;font-size:20px;color:#e1e1e1;padding:2px 0;letter-spacing:1px}
.hint{font-size:11px;color:#9b9b9b;margin-top:-4px}
.dd{display:flex;align-items:center;gap:2px;font-size:11px;font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:#03a9f4;min-width:70px;position:relative}
.dd svg{width:16px;height:16px;fill:currentColor}
.menu{position:absolute;top:20px;left:-6px;background:#2a2a2a;border-radius:6px;box-shadow:0 4px 14px rgba(0,0,0,.5);padding:4px 0;z-index:2;min-width:150px;letter-spacing:0;text-transform:none}
.menu div{display:flex;align-items:center;gap:8px;padding:7px 12px;font-size:13px;font-weight:400;color:#e1e1e1}
.menu div.sel{background:rgba(3,169,244,.14)}
.menu svg{fill:#9b9b9b}
.divider{height:1px;background:rgba(255,255,255,.06)}
.note{grid-column:1/-1;font-size:12.5px;color:var(--muted-foreground);border-left:3px solid var(--border);padding:4px 10px}
</style></head><body><div class="wrap">

<div class="opt"><h3>A · Icon tabs over one field — PIN selected</h3>
<p>Your proposal. Tabs appear only when the entry offers more than one type. A green dot marks each type that holds a value.</p>
<div class="ha"><div class="hero">
 <div class="meta"><div class="icon"><svg viewBox="0 0 24 24"><path d="{{mdiKey}}"/></svg></div><span class="chip">Active</span><svg class="del" viewBox="0 0 24 24"><path d="{{mdiDelete}}"/></svg></div>
 <h2 class="name">Alex</h2>
 <div class="tabs"><span class="tab on"><svg viewBox="0 0 24 24"><path d="{{mdiDialpad}}"/></svg>PIN<span class="dot"></span></span><span class="tab"><svg viewBox="0 0 24 24"><path d="{{mdiFormTextboxPassword}}"/></svg>Password<span class="dot"></span></span></div>
 <div class="row"><span class="val">••••••</span><svg class="eye" viewBox="0 0 24 24"><path d="{{mdiEye}}"/></svg><span class="sw"></span></div>
</div></div></div>

<div class="opt"><h3>A · Icon tabs — editing the password</h3>
<p>Same field, now in password mode with a text keyboard. The lock's length range appears under the field, so a too-short value is refused with a reason.</p>
<div class="ha"><div class="hero">
 <div class="meta"><div class="icon"><svg viewBox="0 0 24 24"><path d="{{mdiKey}}"/></svg></div><span class="chip">Active</span><svg class="del" viewBox="0 0 24 24"><path d="{{mdiDelete}}"/></svg></div>
 <h2 class="name">Alex</h2>
 <div class="tabs"><span class="tab"><svg viewBox="0 0 24 24"><path d="{{mdiDialpad}}"/></svg>PIN<span class="dot"></span></span><span class="tab on"><svg viewBox="0 0 24 24"><path d="{{mdiFormTextboxPassword}}"/></svg>Password<span class="dot"></span></span></div>
 <div class="row"><span class="input">front-porch-42</span><span class="sw"></span></div>
 <div class="hint">8–32 characters on Front Door · letters, digits, symbols, spaces</div>
</div></div></div>

<div class="opt"><h3>B · The label becomes a type picker</h3>
<p>Takes the same space as today's card: the "PIN" label opens a menu. Smallest change, but the picker is hard to discover and you can only see the selected type.</p>
<div class="ha"><div class="hero">
 <div class="meta"><div class="icon"><svg viewBox="0 0 24 24"><path d="{{mdiKey}}"/></svg></div><span class="chip">Active</span><svg class="del" viewBox="0 0 24 24"><path d="{{mdiDelete}}"/></svg></div>
 <h2 class="name">Alex</h2>
 <div class="row"><span class="dd">PIN<svg viewBox="0 0 24 24"><path d="{{mdiChevronDown}}"/></svg>
   <span class="menu"><div class="sel"><svg width="16" height="16" viewBox="0 0 24 24"><path d="{{mdiDialpad}}"/></svg>PIN <span class="dot"></span></div><div><svg width="16" height="16" viewBox="0 0 24 24"><path d="{{mdiFormTextboxPassword}}"/></svg>Password <span class="dot"></span></div></span></span>
  <span class="val">••••••</span><svg class="eye" viewBox="0 0 24 24"><path d="{{mdiEye}}"/></svg><span class="sw"></span></div>
 <div style="height:58px"></div>
</div></div></div>

<div class="opt"><h3>C · One row per available type</h3>
<p>Every credential is visible at once, with no hidden state. It adds one row per type: two rows now, four once RFID and NFC arrive.</p>
<div class="ha"><div class="hero">
 <div class="meta"><div class="icon"><svg viewBox="0 0 24 24"><path d="{{mdiKey}}"/></svg></div><span class="chip">Active</span><svg class="del" viewBox="0 0 24 24"><path d="{{mdiDelete}}"/></svg></div>
 <div class="row"><h2 class="name" style="flex:1">Alex</h2><span class="sw"></span></div>
 <div class="row"><span class="lbl">PIN</span><span class="val small">••••••</span><svg class="eye" viewBox="0 0 24 24"><path d="{{mdiEye}}"/></svg></div>
 <div class="divider"></div>
 <div class="row"><span class="lbl">Password</span><span class="val small">••••••••••</span><svg class="eye" viewBox="0 0 24 24"><path d="{{mdiEye}}"/></svg></div>
</div></div></div>

<div class="note">With every option, an entry whose locks only take PINs shows exactly today's card: no tabs, no picker, no extra rows.</div>
</div></body></html>
EOF
python3 -c "
import json;p=json.load(open('icons.json'));t=open('template.html').read()
for k,v in p.items(): t=t.replace('{{'+k+'}}',v)
open('mock.html','w').write(t);print(len(t))"

