input.command:
curl -sS -m 15 https://www.githubstatus.com/api/v2/summary.json | python3 -c "
import json,sys
d=json.load(sys.stdin)
print('status:', d['status']['description'])
for c in d['components']:
    if c['status']!='operational': print(' ', c['name'], '-', c['status'])
for i in d.get('incidents',[]):
    print('incident:', i['name'], '|', i['status'], '|', i['updated_at'])
    for u in i['incident_updates'][:2]: print('   ', u['body'][:200])
"

