s=s[:start]+'''async def test_only_a_pin_is_remembered_and_an_untracked_pin_keeps_its_own(
    hass: HomeAssistant, mock_lock_config_entry, hass_storage
) -> None:
    """A slot whose PIN the worker does not track keeps the PIN's last write."""
    key = er.async_get(hass).async_get(LOCK_1_ENTITY_ID).id
    hass_storage[SAVED_KEY] = {
        "version": STORE_VERSION,
        "minor_version": 1,
        "key": SAVED_KEY,
        "data": {
            "locks": {
                key: {
                    "entity_id": LOCK_1_ENTITY_ID,
                    "answered": True,
                    "slots": {"1": {"wrote": "old"}},
                }
            }
        },
    }
    store = LockStore(hass)
    await store.async_load()
    password = CredentialAddress(1, CredentialType.PASSWORD)
    # Never started, so the port is never asked anything.
    worker = LockWorker(object(), b"salt")
    worker.slots[password] = Slot("secret", wrote="new")

    store.remember(key, LOCK_1_ENTITY_ID, worker, lambda slot: None)

    assert store.wrote(key, pin_address(1)) == "old"
    assert store.wrote(key, password) is None
    assert _record(hass)["slots"] == {"1": {"wrote": "old"}}
'''
s=s.replace("from copy import deepcopy\n","")
open(p,"w").write(s)
EOF
